-- Версия 1.0.0: исправления по итогам полной проверки перед 1.0.0. Повторный запуск безопасен.
select public.add_site_release('1.0.0','Версия 1.0: полная проверка и исправления по всему сайту',
  jsonb_build_array(
    jsonb_build_object('kind','fixed','scope','site','min_rank',1,'text','Вход: при неверном пароле форма больше не очищается и показывает, что не так.'),
    jsonb_build_object('kind','fixed','scope','site','min_rank',1,'text','После выхода следующий пользователь этого компьютера не видит данные и последний набор предыдущего.'),
    jsonb_build_object('kind','fixed','scope','site','min_rank',1,'text','Генератор: карточка «Готово» скачивает нынешний состав набора, даже если его правили в «Архиве билетов».'),
    jsonb_build_object('kind','fixed','scope','site','min_rank',1,'text','Кнопка «Привязать другой чат» в окне Telegram снова выдаёт код и ссылку.'),
    jsonb_build_object('kind','fixed','scope','site','min_rank',1,'text','На узких телефонах страницы больше не уезжают вбок: шапка, форма вопроса, предметы и темы, статистика.'),
    jsonb_build_object('kind','improved','scope','site','min_rank',1,'text','Окна и нижние меню закрываются клавишей Esc и удерживают фокус внутри; при настройке «уменьшить движение» анимации отключаются.'),
    jsonb_build_object('kind','fixed','scope','site','min_rank',1,'text','Банк вопросов: при листании страниц вопросы не повторяются и не пропускаются, удалённые фильтры сбрасываются сами.'),
    jsonb_build_object('kind','fixed','scope','site','min_rank',2,'text','Форма вопроса: новый вопрос нельзя сохранить в удалённую тему, а картинки не теряются, если сохранить во время их загрузки.'),
    jsonb_build_object('kind','fixed','scope','site','min_rank',2,'text','Массовый импорт: вопросы не попадают в чужую или выдуманную главу, новая тема не создаётся дважды, рисунки в формате EMF/WMF не превращаются в битые картинки.'),
    jsonb_build_object('kind','fixed','scope','site','min_rank',2,'text','Качество банка: во время проверки предмет не переключается, результаты не смешиваются между предметами.'),
    jsonb_build_object('kind','fixed','scope','site','min_rank',3,'text','Корзина: вопрос удалённой темы нельзя вернуть так, чтобы он незаметно попадал в билеты; откатанные партии показывают дату удаления.'),
    jsonb_build_object('kind','fixed','scope','site','min_rank',4,'text','Архив билетов: удалённый набор больше не появляется снова, а «Отменить» не остаётся на экране, когда удаление уже выполнено.'),
    jsonb_build_object('kind','fixed','scope','site','min_rank',4,'text','Экзамен-кластер: при смене набора или предмета не собирается книжка из прежнего набора; вопросы к тексту не берутся без текста.'),
    jsonb_build_object('kind','fixed','scope','site','min_rank',4,'text','Своя игра: экран команды не откатывается назад при медленной связи, команда не вылетает из игры из-за устаревшего ответа сервера.'),
    jsonb_build_object('kind','fixed','scope','app','min_rank',1,'text','Проверка бланков: живая камера работает и не перезапускается после каждого снимка, двойное нажатие не добавляет бланк дважды.'),
    jsonb_build_object('kind','fixed','scope','app','min_rank',1,'text','Мини-приложение: двойное нажатие «Создать и отправить» не создаёт два набора; при обрыве связи есть кнопка «Повторить».'),
    jsonb_build_object('kind','fixed','scope','bot','min_rank',1,'text','Бот: главы и темы со знаками < > & в названии больше не останавливают пошаговый выбор.'),
    jsonb_build_object('kind','fixed','scope','bot','min_rank',4,'text','Безопасность: роль «Учитель игры» не получает вопросы банка через бота и мини-приложение; создание пользователя не сообщает об успехе, если роль не применилась.')
  ),
  '2026-11-22 03:30:00+05');
